///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면이 최초 로드될때 실행되는 초기화 이벤트(초기 데이터 조회나 컴포넌트 설정 — 현재 처리 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트(주로 SPA 환경에서 전역 자원 해제·메모리 누수 방지 — 현재 처리 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getProvider
 * @description URL 분리 처리 — 프레임 소스 URL의 쿼리스트링을 분리해 반환한다.
 * @returns {String} URL 쿼리스트링(없으면 undefined)
 * @hidden N
 * @example const provider = scwin.getProvider();
 */
scwin.getProvider = function() {
    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    const url = $c.frame.srcUrl;
    const arr = url.split("?")[1];
    return (arr.length >= 1 ? arr : undefined);
};

/**
 * @method
 * @name closeWin
 * @description 화면을 종료 처리 — 팝업을 닫는다.
 * @returns {void}
 * @hidden N
 * @example await scwin.closeWin();
 */
scwin.closeWin = async function() {
    await $c.win.closePopup();
};
